+        Some(ct) => {
+            c.z(*ct);
+            c.ccz(*ct, *ta, *tb);
+            c.cz(*ct, *c_prev);
+        }
+        None => {
+            c.neg();
+            c.cz(*ta, *tb);
+            c.z(*c_prev);
+        }
+    };
+    match cap {
