+            let lo = s - k;
+            let zcin = circ.alloc_qubit();
+            super::comparator::compare_geq_cin_middle(circ, &a[lo..], &b[lo..], &zcin, deposit);
+            circ.zero_and_free(zcin);
+        }
+        _ => {
+            super::comparator::compare_geq_cin_middle(circ, a, b, carry, deposit);
+        }
+    }
+    circ.pop_condition();
